import{_ as a,c as p,o as t,ah as n}from"./chunks/framework.BxT5r71R.js";const c=JSON.parse('{"title":"2023年表","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/0_2023年表.md","filePath":"zh-cn/Management2/PART2/0_2023年表.md"}'),i={name:"zh-cn/Management2/PART2/0_2023年表.md"};function o(r,e,S,_,s,E){return t(),p("div",null,[...e[0]||(e[0]=[n('<h2 id="第二部分" tabindex="-1">第二部分 <a class="header-anchor" href="#第二部分" aria-label="Permalink to &quot;第二部分&quot;">​</a></h2><p>2023年的BMSG</p><p>2023年1月13日 纪录节目《MISSIONx2》在BMSG YouTube频道上线，记录MAZZEL的组建历程。</p><p>2023年2月1日 《D.U.N.K. -DANCE UNIVERSE NEVER KILLED-》开播。</p><p>2023年2月24日 BE:FIRST顺利完成首次单独巡演BE:FIRST 1st One Man Tour “BE:1” 2022-2023。</p><p>2023年3月1日 粉丝社区B-Town改版，以线上会员社区的形式重新开放。</p><p>2023年3月5日 D.U.N.K. Showcase首次举办，首场演出在有明体育馆举行。2023年3月11日、12日还在幕张展览馆举行演出。</p><p>2023年3月22日 edhiii boi发行首张专辑《edhiii boi is here》。</p><p>2023年4月4日 BMSG首次举办Greeting &amp; Gathering聚会，邀请相关人士参加。</p><p>2023年5月13日 《D.U.N.K.》YouTube音乐节目上线。</p><p>2023年5月17日 MAZZEL发行单曲《Vivid》，正式出道。</p><p>2023年5月27日 SKY-HI在东京代代木第一体育馆启动个人迄今规模最大的体育馆巡演SKY-HI ARENA TOUR 2023 -BOSSDOM-。</p><p>2023年8月25日 BE:FIRST首部演唱会纪录片《BE:the ONE》上映。</p><p>2023年8月30日 SKY-HI的《Sarracenia》与BE:FIRST的《Salvia》以Split单曲（双艺人合作单曲）的形式发行。</p><p>2023年9月13日 BE:FIRST发行单曲《Mainstream》。</p><p>2023年9月18日 BMSG成立3周年。</p><p>2023年9月23日、24日 第二届BMSG FES在东京体育馆举办。2023年9月30日、10月1日还在大阪城音乐厅举行演出。</p><p>2023年10月6日 REIKO发行出道单曲《BUTTERFLY》。</p><p>2023年11月4日 BMSG与Chanmina宣布联合举办女子组合选秀No No Girls，并于当天启动招募。</p><p>2023年12月2日、3日 D.U.N.K. Showcase in KYOCERA DOME OSAKA在京瓷巨蛋大阪举办。</p>',20)])])}const h=a(i,[["render",o]]);export{c as __pageData,h as default};
